<?php session_start(); if(!isset($_SESSION['id'])||$_SESSION['role']!=='admin'){header('Location:dashboard.php');exit;} include 'db.php'; if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:add_book.php');exit;}$book=trim($_POST['book_name']??'');$author=trim($_POST['author']??'');$category=trim($_POST['category']??'');$isbn=trim($_POST['isbn']??'');$qty=(int)($_POST['quantity']??0);if($book===''||$author===''||$category===''||$isbn===''||$qty<1){header('Location:add_book.php?invalid=1');exit;}$s=$conn->prepare('SELECT id FROM books WHERE isbn=? LIMIT 1');$s->bind_param('s',$isbn);$s->execute();$s->store_result();if($s->num_rows){$s->close();header('Location:add_book.php?exists=1');exit;}$s->close();$s=$conn->prepare('INSERT INTO books(book_name,author,category,isbn,quantity) VALUES(?,?,?,?,?)');$s->bind_param('ssssi',$book,$author,$category,$isbn,$qty);$ok=$s->execute();$s->close();header('Location:add_book.php?'.($ok?'success=1':'invalid=1'));exit;
